const hlB = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10), new THREE.MeshBasicMaterial({ color: 0xff0000 }));
hlGroup.add(hlLine, hlA, hlB);
scene.add(hlGroup);

/* ---------- carried square (linear only) ---------- */
const carPos = new Float32Array(16 * 3);
const carGeo = new THREE.BufferGeometry();
carGeo.setAttribute('position', new THREE.BufferAttribute(carPos, 3));
const carLines = new THREE.LineSegments(carGeo, new THREE.LineDashedMaterial({
  color: C_GUIDE, dashSize: 0.14, gapSize: 0.1, transparent: true, opacity: 0.95
