carLines.frustumCulled = false;
scene.add(carLines);

/* ---------- mapping ---------- */
let mapping = 'linear';
const sldRot = document.getElementById('sldRot');
const sldStr = document.getElementById('sldStr');
const sldBias = document.getElementById('sldBias');

function affine(u, v, th, s) {
  const c = Math.cos(th), si = Math.sin(th);
  const ru = c * u - si * v, rv = si * u + c * v;
  return [s * ru, rv / s];
}
function mapPoint(u, v) {
  const th = THREE.MathUtils.degToRad(+sldRot.value);
  const s = +sldStr.value, b = +sldBias.value;
  if (mapping === 'linear') {
    const a = affine(u, v, th, s);
    return [1.15 * a[0] + b * 1.1, 1.15 * a[1] + b * 0.7];
  }
