const CAR_CAP = 3.2;
function rebuild() {
  for (let i = 0; i < N; i++) {
    const [ou, ov] = mapPoint(inU[i], inV[i]);
    outU[i] = ou; outV[i] = ov;
    const inside = Math.abs(ou) <= H + 1e-6 && Math.abs(ov) <= H + 1e-6;
    shown[i] = inside ? 1 : 0;

    dummy.scale.setScalar(inside ? 1 : 0.0001);
    dummy.position.set(ou, Y_OUT, ov); dummy.updateMatrix();
    dotsOut.setMatrixAt(i, dummy.matrix);

    dummy.position.set(inU[i], Y_IN, inV[i]); dummy.updateMatrix();
    pickMesh.setMatrixAt(i, dummy.matrix);

    const k = i * 6;
    trajPos[k] = inU[i]; trajPos[k + 1] = Y_IN; trajPos[k + 2] = inV[i];
    if (inside) {
      trajPos[k + 3] = ou; trajPos[k + 4] = Y_OUT; trajPos[k + 5] = ov;
    } else {
      trajPos[k + 3] = inU[i]; trajPos[k + 4] = Y_IN; trajPos[k + 5] = inV[i];
