// @FIGURE_CODE_BEGIN
/* ── Element spec (per panel) ─────────────────────────────────────────────
 * input plane outline  → 4 × Mesh BoxGeometry(4.05,0.04,0.045)  #3C3C3C
 * input plane grid     → LineSegments u,v=-1,0,1 + 2 diagonals  #D8D8D8
 * output plane outline → 4 × Mesh BoxGeometry, y=+1.5           #3C3C3C
 * output plane grid    → LineSegments (same ruling)             #D8D8D8
 * corner guides        → LineSegments dashed, 4 verticals       #9A9A9A
 * input dots (320)     → InstancedMesh SphereGeometry(0.033)    #FF2A2A
 * output dots (320)    → InstancedMesh SphereGeometry(0.033)    #FF2A2A
 * trajectories (320)   → LineSegments LineDashedMaterial op .32 #FF2A2A
 * carried square       → LineSegments dashed loop + connectors  #8A8A8A
 * picking proxies      → InstancedMesh SphereGeometry(0.12) op 0
 * highlight (global)   → Line dashed + 2 × Sphere(0.08)         #FF0000
 * labels               → addLabel: x_in, x_out (18px bold), monospace title
 * ─────────────────────────────────────────────────────────────────────── */

const C_OUTLINE = 0x3c3c3c, C_GRID = 0xd8d8d8, C_GUIDE = 0x9a9a9a,
      C_CARRY = 0x8a8a8a, C_RED = 0xff2a2a;
const Y_IN = -1.5, Y_OUT = 1.5, H = 2;
const N = 320, SIG = 0.55;
const PANEL_GAP = 6.2;

/* ---------- fixed input samples (built once, reused by every mapping) ---- */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240617);
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = rnd();
  while (v === 0) v = rnd();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
