/* ---------- mappings ---------- */
const sldRot = document.getElementById('sldRot');
const sldStr = document.getElementById('sldStr');
const sldBias = document.getElementById('sldBias');

function affine(u, v, th, s) {
  const c = Math.cos(th), si = Math.sin(th);
  const ru = c * u - si * v, rv = si * u + c * v;
  return [s * ru, rv / s];
}
function mapPoint(name, u, v) {
  const th = THREE.MathUtils.degToRad(+sldRot.value);
  const s = +sldStr.value, b = +sldBias.value;
  if (name === 'linear') {
    const a = affine(u, v, th, s);
    // bias drifts the whole cloud clearly off-center → visibly slanted sheaf
    return [1.15 * a[0] + b * 1.85, 1.15 * a[1] + b * 1.15];
  }
  if (name === 'relu') {
    const a = affine(u, v, th, s);
    return [1.4 * Math.max(0, a[0] + b * 0.3), 1.4 * Math.max(0, a[1] + b * 0.3)];
  }
  const n = Math.hypot(u, v) || 1e-6;
  return [1.7 * u / n, 1.7 * v / n];
}

/* ---------- shared geometry/material prototypes ---------- */
const outlineMat = new THREE.MeshBasicMaterial({ color: C_OUTLINE });
const gridMat = new THREE.LineBasicMaterial({ color: C_GRID });
const dotGeo = new THREE.SphereGeometry(0.033, 8, 6);
const pickGeo = new THREE.SphereGeometry(0.12, 6, 5);
const dummy = new THREE.Object3D();

function edgeBar(x1, z1, x2, z2, y) {
  const len = Math.hypot(x2 - x1, z2 - z1) + 0.045;
  const m = new THREE.Mesh(new THREE.BoxGeometry(len, 0.04, 0.045), outlineMat);
  m.position.set((x1 + x2) / 2, y, (z1 + z2) / 2);
  m.rotation.y = -Math.atan2(z2 - z1, x2 - x1);
