}
function buildPlane(parent, y) {
  const cs = [[-H, -H], [H, -H], [H, H], [-H, H]];
  for (let i = 0; i < 4; i++) {
    const a = cs[i], b = cs[(i + 1) % 4];
    parent.add(edgeBar(a[0], a[1], b[0], b[1], y));
  }
  const gp = [];
  for (let i = -1; i <= 1; i++) {
    gp.push(new THREE.Vector3(i, y, -H), new THREE.Vector3(i, y, H));
    gp.push(new THREE.Vector3(-H, y, i), new THREE.Vector3(H, y, i));
  }
