  const P = {
    name, root, visible: true,
    outU: new Float32Array(N), outV: new Float32Array(N), shown: new Uint8Array(N),
    matIn, matOut, trajMat, pickMesh, dotsOut, trajGeo, trajPos, carGeo, carPos, carLines,
    labels: []
