      const ou = r[0], ov = r[1];
      P.outU[i] = ou; P.outV[i] = ov;
      const inside = Math.abs(ou) <= H + 1e-6 && Math.abs(ov) <= H + 1e-6;
      P.shown[i] = inside ? 1 : 0;

      dummy.scale.setScalar(inside ? 1 : 0.0001);
      dummy.position.set(ou, Y_OUT, ov); dummy.updateMatrix();
      P.dotsOut.setMatrixAt(i, dummy.matrix);

      dummy.scale.setScalar(1);
      dummy.position.set(inU[i], Y_IN, inV[i]); dummy.updateMatrix();
      P.pickMesh.setMatrixAt(i, dummy.matrix);

      const k = i * 6;
      trajPos[k] = inU[i]; trajPos[k + 1] = Y_IN; trajPos[k + 2] = inV[i];
      if (inside) { trajPos[k + 3] = ou; trajPos[k + 4] = Y_OUT; trajPos[k + 5] = ov; }
      else { trajPos[k + 3] = inU[i]; trajPos[k + 4] = Y_IN; trajPos[k + 5] = inV[i]; }
    }
    P.dotsOut.instanceMatrix.needsUpdate = true;
    P.pickMesh.instanceMatrix.needsUpdate = true;
    trajGeo.attributes.position.needsUpdate = true;
    trajGeo.computeBoundingSphere();
    traj.computeLineDistances();

    if (name === 'linear') {
      const base = [[-H, -H], [H, -H], [H, H], [-H, H]];
      let img = base.map(c => mapPoint(name, c[0], c[1]));
      let m = 0;
      img.forEach(p => { m = Math.max(m, Math.abs(p[0]), Math.abs(p[1])); });
