      }
      for (let i = 0; i < 4; i++) push(src[i][0], Y_IN, src[i][1], 0), push(img[i][0], Y_OUT, img[i][1]);
      carGeo.attributes.position.needsUpdate = true;
      carGeo.computeBoundingSphere();
      carLines.computeLineDistances();
    }
  };

  P.setVisible = function (v) {
    P.visible = v;
    root.visible = v;
    P.labels.forEach(L => { L.div.style.opacity = v ? '1' : '0'; });
  };

  P.rebuild();
  return P;
}

const panels = [makePanel('linear'), makePanel('relu'), makePanel('L2-norm')];
const byName = {}; panels.forEach(p => byName[p.name] = p);

/* ---------- highlight (shared) ---------- */
const hlGroup = new THREE.Group(); hlGroup.visible = false;
const hlGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const hlLine = new THREE.Line(hlGeo, new THREE.LineDashedMaterial({ color: 0xff0000, dashSize: 0.11, gapSize: 0.07 }));
const hlA = new THREE.Mesh(new THREE.SphereGeometry(0.075, 12, 10), new THREE.MeshBasicMaterial({ color: 0xff0000 }));
const hlB = new THREE.Mesh(new THREE.SphereGeometry(0.075, 12, 10), new THREE.MeshBasicMaterial({ color: 0xff0000 }));
hlGroup.add(hlLine, hlA, hlB);
scene.add(hlGroup);

/* ---------- state ---------- */
let mapping = 'linear';
let compare = false;
panels.forEach(p => p.setVisible(p.name === mapping));

/* ---------- camera ---------- */
function fitCamera() {
  setCameraView({
    projection: 'orthographic',
    axisScreenAngles: { x: 30, z: 30 },
    heightFraction: compare ? 0.6 : 0.68,
    target: [0, 0, 0]
  });
}
fitCamera();
controls.minPolarAngle = THREE.MathUtils.degToRad(30);   // elevation 60°
controls.maxPolarAngle = THREE.MathUtils.degToRad(82);   // elevation 8°
controls.enablePan = false;
document.getElementById('btnReset').style.display = '';

/* ---------- labels ---------- */
function addPanelLabels(P) {
  const mk = (html, pos, opts) => {
    const L = addLabel(html, pos, opts);
    L.baseX = pos.x;
    P.labels.push(L);
    return L;
  };
  mk('<b>x</b><sub>out</sub>', new THREE.Vector3(-H, Y_OUT, H),
    { fontSize: '18px', bold: true, offset: [-34, -20] });
  mk('<b>x</b><sub>in</sub>', new THREE.Vector3(-H, Y_IN, H),
    { fontSize: '18px', bold: true, offset: [-32, 24] });
  // title raised well clear of the top plane's back corner
  const t = mk(P.name, new THREE.Vector3(0, Y_OUT + 2.6, 0),
    { fontSize: '24px', bold: true, offset: [0, -6] });
  t.div.style.fontFamily = 'ui-monospace, Consolas, monospace';
  t.div.style.letterSpacing = '0.5px';
  P.titleLbl = t;
}
panels.forEach(addPanelLabels);
panels.forEach(p => p.setVisible(p.visible));

/* ---------- layout / mode ---------- */
function layout() {
  panels.forEach((p, i) => {
    const x = compare ? (i - 1) * PANEL_GAP : 0;
    p.root.position.x = x;
    p.labels.forEach(L => { L.pos.x = L.baseX + x; });
    p.setVisible(compare ? true : p.name === mapping);
    if (p.titleLbl) p.titleLbl.div.style.fontSize = compare ? '19px' : '24px';
  });
  fitCamera();
}

/* ---------- hover ---------- */
const ray = new THREE.Raycaster();
const ptr = new THREE.Vector2();
let hoverPanel = null, hoverIdx = -1;

function dimAll(on) {
  panels.forEach(p => {
    p.trajMat.opacity = on ? 0.06 : 0.32;
    p.matIn.opacity = on ? 0.16 : 1;
    p.matOut.opacity = on ? 0.16 : 1;
  });
}
function applyHover(P, i) {
  dimAll(true);
  const dx = P.root.position.x;
  const a = new THREE.Vector3(inU[i] + dx, Y_IN, inV[i]);
  const b = new THREE.Vector3(P.outU[i] + dx, Y_OUT, P.outV[i]);
  hlGeo.setFromPoints([a, b]);
  hlLine.computeLineDistances();
  hlA.position.copy(a); hlB.position.copy(b);
  hlGroup.visible = true;
}
function clearHover() {
  hoverPanel = null; hoverIdx = -1;
  dimAll(false);
  hlGroup.visible = false;
  hideTooltip();
}
canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ptr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  ray.setFromCamera(ptr, camera);
  const targets = panels.filter(p => p.visible).map(p => p.pickMesh);
  const hits = targets.length ? ray.intersectObjects(targets, false) : [];
  let gotP = null, gotI = -1;
  for (const h of hits) {
    const P = panels.find(p => p.pickMesh === h.object);
    if (P && h.instanceId !== undefined && P.shown[h.instanceId]) { gotP = P; gotI = h.instanceId; break; }
  }
  if (gotP) {
    hoverPanel = gotP; hoverIdx = gotI;
    applyHover(gotP, gotI);
    canvas.style.cursor = 'pointer';
    showTooltip(`${gotP.name}: (${inU[gotI].toFixed(2)}, ${inV[gotI].toFixed(2)}) → (${gotP.outU[gotI].toFixed(2)}, ${gotP.outV[gotI].toFixed(2)})`, e);
  } else if (hoverIdx >= 0) {
    clearHover();
    canvas.style.cursor = 'grab';
  }
});
canvas.addEventListener('pointerleave', clearHover);

/* ---------- rebuild all ---------- */
function rebuildAll() {
  panels.forEach(p => p.rebuild());
  if (hoverPanel && hoverIdx >= 0) {
    if (hoverPanel.shown[hoverIdx]) applyHover(hoverPanel, hoverIdx); else clearHover();
  }
}

/* ---------- UI wiring ---------- */
const btns = {
  linear: document.getElementById('btnLinear'),
  relu: document.getElementById('btnRelu'),
  'L2-norm': document.getElementById('btnL2')
};
const btnCompare = document.getElementById('btnCompare');

function refreshUI() {
  document.getElementById('valRot').textContent = (+sldRot.value).toFixed(0);
  document.getElementById('valStr').textContent = (+sldStr.value).toFixed(2);
  document.getElementById('valBias').textContent = (+sldBias.value).toFixed(2);
  const off = (!compare && mapping === 'L2-norm');
  [['lblRot', sldRot], ['lblStr', sldStr], ['lblBias', sldBias]].forEach(([id, s]) => {
    s.disabled = off;
    document.getElementById(id).style.opacity = off ? 0.4 : 1;
  });
  for (const k in btns) btns[k].classList.toggle('active', !compare && k === mapping);
  btnCompare.classList.toggle('active', compare);
  btnCompare.textContent = compare ? 'Single panel' : 'Compare all three';
}
function setMapping(m) {
  mapping = m; compare = false;
  clearHover(); layout(); refreshUI(); rebuildAll();
}
for (const k in btns) btns[k].addEventListener('click', () => { tween = null; setMapping(k); });
btnCompare.addEventListener('click', () => {
  tween = null; compare = !compare;
  clearHover(); layout(); refreshUI(); rebuildAll();
});
[sldRot, sldStr, sldBias].forEach(s =>
  s.addEventListener('input', () => { tween = null; refreshUI(); rebuildAll(); }));

/* ---------- guided steps ---------- */
const steps = [
  { title: 'Linear layer', narration: 'A Gaussian blob on the input plane is carried up to a tilted, off-center cloud; the dashed gray quadrilateral shows where the input square itself landed.', state: { mappingType: 'linear', rotation: 25, stretch: 1.6, bias: 0.4 } },
  { title: 'Turning the weights', narration: 'Sweeping rotation and stretch shears and spins both the cloud and the carried square together — the same matrix acts on every sample at once.', state: { mappingType: 'linear', rotation: -50, stretch: 2.2, bias: 0 } },
  { title: 'Bias drift', narration: "Bias translates the entire output cloud rigidly off the plane's center without changing its shape.", state: { mappingType: 'linear', rotation: 25, stretch: 1.6, bias: 1.1 } },
  { title: 'ReLU layer', narration: 'Clipping negative coordinates piles the trajectories into a narrow wedge hugging the two edges that meet at one corner — a large part of the distribution is squashed onto the boundary.', state: { mappingType: 'relu', rotation: 25, stretch: 1.6, bias: 0.4 } },
  { title: 'L2-norm layer', narration: 'Normalizing each sample discards its magnitude: the trajectories fan outward and every point lands on a ring near the plane boundary.', state: { mappingType: 'L2-norm', rotation: 0, stretch: 1, bias: 0 } }
];
let stepIdx = 0, tween = null;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}. ${s.title}`;
  document.getElementById('stepNarr').textContent = s.narration;
  mapping = s.state.mappingType;
  compare = false;
  clearHover(); layout();
  tween = {
    from: { rotation: +sldRot.value, stretch: +sldStr.value, bias: +sldBias.value },
    to: { rotation: s.state.rotation, stretch: s.state.stretch, bias: s.state.bias },
    t0: performance.now(), dur: 750
  };
  refreshUI();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

function tickTween() {
  requestAnimationFrame(tickTween);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  sldRot.value = tween.from.rotation + (tween.to.rotation - tween.from.rotation) * e;
  sldStr.value = tween.from.stretch + (tween.to.stretch - tween.from.stretch) * e;
  sldBias.value = tween.from.bias + (tween.to.bias - tween.from.bias) * e;
  refreshUI(); rebuildAll();
  if (k >= 1) tween = null;
}
tickTween();

document.getElementById('stepNarr').textContent = steps[0].narration;
refreshUI();
rebuildAll();
